-- Function: public.fn_get_family_pickup_relationships
-- Backup generated on 2026-10-25 20:33:23

CREATE OR REPLACE FUNCTION public.fn_get_family_pickup_relationships(p_tenant_id uuid, p_child_id uuid)  RETURNS TABLE(id uuid, child_id uuid, person_id uuid, relationship character varying, is_primary boolean, is_emergency boolean, full_name character varying, phone character varying, photo_url text)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     WITH guardians AS (         SELECT              fr.id AS g_id,             fr.child_id AS g_child_id,             COALESCE(p.id, u.id) AS g_person_id,             COALESCE(fr.relationship, p.relationship, 'Legal Guardian')::VARCHAR AS g_relationship,             fr.is_primary AS g_is_primary,             FALSE AS g_is_emergency,             COALESCE(NULLIF(TRIM(p.first_name || ' ' || p.last_name), ''), NULLIF(TRIM(u.first_name || ' ' || u.last_name), ''), u.display_name, 'Parent / Guardian')::VARCHAR AS g_full_name,             COALESCE(p.mobile_phone, p.alternate_phone)::VARCHAR AS g_phone,             NULL::TEXT AS g_photo_url         FROM family_relationships fr         JOIN users u ON fr.user_id = u.id         LEFT JOIN persons p ON p.user_id = u.id         WHERE fr.tenant_id = p_tenant_id AND fr.child_id = p_child_id           AND (fr.status IS NULL OR fr.status = 'Verified')           AND fr.revoked_at IS NULL          UNION ALL          SELECT              cg.id AS g_id,             cg.child_id AS g_child_id,             p.id AS g_person_id,             COALESCE(cg.relationship, p.relationship, 'Legal Guardian')::VARCHAR AS g_relationship,             cg.is_primary AS g_is_primary,             FALSE AS g_is_emergency,             COALESCE(NULLIF(TRIM(p.first_name || ' ' || p.last_name), ''), 'Parent / Guardian')::VARCHAR AS g_full_name,             COALESCE(p.mobile_phone, p.alternate_phone)::VARCHAR AS g_phone,             NULL::TEXT AS g_photo_url         FROM child_guardians cg         JOIN persons p ON cg.person_id = p.id         WHERE cg.tenant_id = p_tenant_id AND cg.child_id = p_child_id           AND (cg.can_pickup = TRUE OR cg.is_primary = TRUE)     )     SELECT DISTINCT ON (g_person_id)            g_id, g_child_id, g_person_id, g_relationship, g_is_primary, g_is_emergency, g_full_name, g_phone, g_photo_url     FROM guardians     ORDER BY g_person_id, g_is_primary DESC; END; $function$ ;
